Clear[P, Q, Py, Qx, mu, P1, Q1, U, x, y, s, x0, y0]
P[x_, y_] = (x + 3)*Sin[y]; Q[x_, y_] = x*Cos[y];
Py[x_, y_] = D[P[x, y], y]; Qx[x_, y_] = D[Q[x, y], x];
Py[x, y] - Qx[x, y] // Simplify       (* no da 0: no es exacta *)
g[x_] = (Py[x, y] - Qx[x, y])/Q[x, y] // Simplify   (* solo depende de x: hay factor integrante mu(x) *)
g[2]

Clear[P, Q, Py, Qx, mu, P1, Q1, U, x, y, s, x0, y0]
P[x_, y_] = (x + 3)*Sin[y]; Q[x_, y_] = x*Cos[y];
Py[x_, y_] = D[P[x, y], y]; Qx[x_, y_] = D[Q[x, y], x];
Py[x, y] - Qx[x, y] // Simplify       (* no da 0: no es exacta *)
g[x_] = (Py[x, y] - Qx[x, y])/Q[x, y] // Simplify   (* solo depende de x: hay factor integrante mu(x) *)
mu[x_] = Exp[Integrate[g[x], x]]
P1[x_, y_] = mu[x]*P[x, y]; Q1[x_, y_] = mu[x]*Q[x, y];   (* ecuación ya exacta *)
x0 = 0; y0 = 0;
U[x_, y_] = Integrate[P1[s, y], {s, x0, x}] + Integrate[Q1[x0, s], {s, y0, y}]
y /. FindRoot[U[2, y] == U[1, Pi/6], {y, 0.1}]

Clear[C1, C2, K1, K2, solH, solG, sol, t, mat, l1, l2, v1, v2]
mat = {{3, 8}, {-1, -3}};
{l1, l2} = Eigenvalues[mat];
{v1, v2} = Eigenvectors[mat];
solH[t_] = C1*v1*Exp[l1*t] + C2*v2*Exp[l2*t];     (* solución de la homogénea *)
solCs = Solve[solH[t] == {Exp[t], 0}, {C1, C2}];   (* son c1'(t) y c2'(t) *)
dCs = {C1, C2} /. Flatten[solCs];
{C1, C2} = Integrate[dCs, t] + {K1, K2};          (* se integran y se añaden constantes *)
solG[t_] = solH[t]                                (* solución general, con K1 y K2 *)
solK = Solve[solG[0] == {1, 0}, {K1, K2}];         (* condiciones iniciales *)
sol[t_] = solG[t] /. Flatten[solK] // Simplify
sol[2][[1]] // N

