Clear[y, Y, ys, t, s]
ecdif = y''[t] - 3 y'[t] + 2 y[t] == Exp[-4 t];
ec1 = LaplaceTransform[ecdif, t, s] /. {y[0] -> 1, y'[0] -> 5};
sol1 = Solve[ec1, LaplaceTransform[y[t], t, s]];
Y[s_] = LaplaceTransform[y[t], t, s] /. Flatten[sol1]   (* transformada de la solución *)
