Clear[i1, i2, e, t, s, L, R1, R2, C1, I2]
R1 = 10; R2 = 5; L = 1; C1 = 1/5;   (* C1 y no C: C está reservada *)
e[t_] = 120*(UnitStep[t] - UnitStep[t - 2]);
ecdifs = {L*i1'[t] + L*i2'[t] + R1*i1[t] == e[t], -R1*i1'[t] + R2*i2'[t] + i2[t]/C1 == 0};
ec1 = LaplaceTransform[ecdifs, t, s] /. {i1[0] -> 0, i2[0] -> 0};
sol1 = Solve[ec1, {LaplaceTransform[i1[t], t, s], LaplaceTransform[i2[t], t, s]}];
I2[s_] = LaplaceTransform[i2[t], t, s] /. Flatten[sol1] // Simplify
I2[1.3]

Clear[a, b, c, d, e, g, x, y, zp, res, sol]
zp = a*x^2 + b*x*y + c*y^2 + d*x + e*y + g;
res = Expand[D[zp, {x, 2}] - D[zp, x, y] - 2 D[zp, x] - 3 D[zp, y] + zp]
(* se iguala coeficiente a coeficiente con 2 x y + y *)
sol = Solve[{2 a - b - 2 d - 3 e + g == 0, -4 a - 3 b + d == 0, a == 0, -2 b - 6 c + e == 1, b == 2, c == 0}, {a, b, c, d, e, g}]
zp /. Flatten[sol] /. {x -> 1, y -> -2}

Clear[a, L, trunc, phi, An, u, solcalor, x, t]
a = 2; L = 5; trunc = 6;
phi[x_] = x*(5 - x);
An[n_Integer] := (2/L)*Integrate[phi[x]*Sin[n*Pi*x/L], {x, 0, L}]
u[x_, t_, nau_Integer] := Sum[An[n]*Exp[-(n*Pi*a/L)^2*t]*Sin[n*Pi*x/L], {n, 1, nau}]
solcalor[x_, t_] = u[x, t, trunc];
solcalor[3, 0.5] // N

