solcalor[x_, t_] = u[x, t, trunc];
t /. FindRoot[solcalor[2.5, t] == 2, {t, 0.5}]

Clear[a, b, trunc, theta, An, u, solLaplace, x, y]
a = 3; b = 5; trunc = 5;
theta[x_] = 2 x^2*(a - x)^3;
An[n_Integer] := (2/(a*Sinh[b*n*Pi/a]))*Integrate[theta[x]*Sin[n*Pi*x/a], {x, 0, a}]
u[x_, y_, nau_Integer] := Sum[An[n]*Sinh[n*Pi*y/a]*Sin[n*Pi*x/a], {n, 1, nau}]
solLaplace[x_, y_] = u[x, y, trunc];
solLaplace[1, 3] // N
